
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_eel_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_eel", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.887182262068169e+00, -4.788318521341855e+00, -4.649693366572241e+00, -4.457468168665014e+00, -4.195115121397988e+00, -3.844985110953267e+00, -3.392004123733952e+00, -2.829626361708018e+00, -2.163817734676292e+00, -1.394877368865827e+00, -5.381200178224996e-01, -3.960464335511097e-01, -6.217887213255221e-01, -5.088749822968741e-01, -3.329540003410407e-01, -1.732033019220727e-01, -6.856960137741032e-02, -2.298657606627008e-02, -3.598575093173999e-03, -1.718047018553934e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


